router_auth:
"""
Rutas de autenticación: /api/auth
- POST /api/auth/login   → verifica credenciales y genera JWT
- GET  /api/auth/me      → perfil del usuario autenticado (protegido)
- GET  /api/auth/roles   → lista de roles (protegido)
"""
from fastapi import APIRouter, Depends, HTTPException, status
from sqlalchemy.orm import Session

from ..database import get_db
from ..models import Rol, Usuario
from ..schemas import LoginRequest, LoginResponse, RolOut, UsuarioOut
from ..security import (
    create_access_token,
    get_current_user,
    usuario_a_dict,
    verify_password,
)

router = APIRouter(prefix='/api/auth', tags=['Autenticación'])


@router.post('/login', response_model=LoginResponse)
def login(body: LoginRequest, db: Session = Depends(get_db)):
    """Inicio de sesión: valida correo y contraseña y retorna un JWT."""
    user = db.query(Usuario).filter(Usuario.correo == body.email.lower().strip()).first()
    if user is None:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail='Correo o contraseña incorrectos.',
        )

    if user.estado != 'activo':
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail='Tu cuenta está desactivada. Contacta al administrador.',
        )

    if not verify_password(body.contrasena, user.contrasena):
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail='Correo o contraseña incorrectos.',
        )

    rol_nombre = user.rol.nombre if user.rol else 'cliente'
    token = create_access_token(
        {'sub': str(user.id), 'correo': user.correo, 'rol': rol_nombre}
    )

    return LoginResponse(
        message='Inicio de sesión exitoso.',
        token=token,
        user={
            'id': user.id,
            'nombre': user.nombre,
            'apellido': user.apellido,
            'correo': user.correo,
            'rol': rol_nombre,
            'rol_id': user.rol_id,
        },
    )


@router.get('/me', response_model=UsuarioOut)
def get_me(current_user: Usuario = Depends(get_current_user)):
    """Perfil del usuario autenticado (requiere token)."""
    return current_user


@router.get('/roles')
def get_roles(
    db: Session = Depends(get_db),
    _: Usuario = Depends(get_current_user),
):
    """Lista de roles del sistema (requiere autenticación)."""
    roles = db.query(Rol).order_by(Rol.id).all()
    return {'roles': [RolOut.model_validate(r).model_dump() for r in roles]}

router_usuarios:
"""
Rutas de usuarios: /api/usuarios
- POST   /api/usuarios/registro     → registro de clientes (público)
- GET    /api/usuarios              → listar usuarios (admin)
- GET    /api/usuarios/{id}         → consultar usuario (admin)
- PUT    /api/usuarios/{id}         → actualizar usuario (admin)
- PATCH  /api/usuarios/{id}/estado  → cambiar estado activo/inactivo (admin)
- DELETE /api/usuarios/{id}         → eliminar usuario (admin)
"""
from fastapi import APIRouter, Depends, HTTPException, status
from sqlalchemy.orm import Session

from ..database import get_db
from ..models import Usuario
from ..schemas import EstadoUpdate, UsuarioRegistro, UsuarioUpdate
from ..security import (
    get_current_user,
    hash_password,
    require_roles,
    usuario_a_dict,
    verify_password,
)

router = APIRouter(prefix='/api/usuarios', tags=['Usuarios'])


@router.post('/registro', status_code=status.HTTP_201_CREATED)
def registrar_usuario(body: UsuarioRegistro, db: Session = Depends(get_db)):
    """Registro de un cliente nuevo: valida datos, verifica duplicados
    y almacena la contraseña con hashing seguro (bcrypt)."""
    correo = body.correo.lower().strip()

    existe_correo = db.query(Usuario).filter(Usuario.correo == correo).first()
    if existe_correo:
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail='El correo ya está registrado.',
        )

    existe_documento = (
        db.query(Usuario)
        .filter(Usuario.numero_documento == body.numero_documento)
        .first()
    )
    if existe_documento:
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail='El número de documento ya está registrado.',
        )

    nuevo = Usuario(
        nombre=body.nombre,
        apellido=body.apellido,
        tipo_documento=body.tipo_documento,
        numero_documento=body.numero_documento,
        direccion=body.direccion,
        telefono=body.telefono,
        correo=correo,
        contrasena=hash_password(body.contrasena),  # Nunca se guarda en texto plano
        rol_id=3,  # Por defecto: cliente
        estado='activo',
    )
    db.add(nuevo)
    db.commit()
    db.refresh(nuevo)

    return {
        'message': 'Usuario registrado exitosamente.',
        'user': {
            'id': nuevo.id,
            'nombre': nuevo.nombre,
            'apellido': nuevo.apellido,
            'correo': nuevo.correo,
            'rol': 'cliente',
        },
    }


@router.get('', response_model=dict)
def listar_usuarios(
    db: Session = Depends(get_db),
    _: Usuario = Depends(require_roles('administrador')),
):
    """Lista todos los usuarios (solo administrador)."""
    usuarios = db.query(Usuario).order_by(Usuario.fecha_registro.desc()).all()
    return {'users': [usuario_a_dict(u) for u in usuarios]}


@router.get('/{usuario_id}', response_model=dict)
def obtener_usuario(
    usuario_id: int,
    db: Session = Depends(get_db),
    _: Usuario = Depends(require_roles('administrador')),
):
    """Consulta un usuario por ID (solo administrador)."""
    usuario = db.query(Usuario).filter(Usuario.id == usuario_id).first()
    if usuario is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail='Usuario no encontrado.',
        )
    return {'user': usuario_a_dict(usuario)}


@router.put('/{usuario_id}')
def actualizar_usuario(
    usuario_id: int,
    body: UsuarioUpdate,
    db: Session = Depends(get_db),
    _: Usuario = Depends(require_roles('administrador')),
):
    """Actualiza los datos de un usuario (solo administrador)."""
    usuario = db.query(Usuario).filter(Usuario.id == usuario_id).first()
    if usuario is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail='Usuario no encontrado.',
        )

    data = body.model_dump(exclude_unset=True, exclude_none=True)

    # Si llega nueva contraseña, se vuelve a hashear
    if 'contrasena' in data:
        if not verify_password(data['contrasena'], usuario.contrasena):
            data['contrasena'] = hash_password(data['contrasena'])
        else:
            del data['contrasena']

    if 'correo' in data:
        correo = data['correo'].lower().strip()
        duplicado = (
            db.query(Usuario)
            .filter(Usuario.correo == correo, Usuario.id != usuario_id)
            .first()
        )
        if duplicado:
            raise HTTPException(
                status_code=status.HTTP_409_CONFLICT,
                detail='El correo ya está registrado.',
            )
        data['correo'] = correo

    if 'numero_documento' in data:
        duplicado = (
            db.query(Usuario)
            .filter(
                Usuario.numero_documento == data['numero_documento'],
                Usuario.id != usuario_id,
            )
            .first()
        )
        if duplicado:
            raise HTTPException(
                status_code=status.HTTP_409_CONFLICT,
                detail='El número de documento ya está registrado.',
            )

    for campo, valor in data.items():
        setattr(usuario, campo, valor)

    db.commit()
    return {'message': 'Usuario actualizado exitosamente.'}


@router.patch('/{usuario_id}/estado')
def cambiar_estado_usuario(
    usuario_id: int,
    body: EstadoUpdate,
    db: Session = Depends(get_db),
    _: Usuario = Depends(require_roles('administrador')),
):
    """Cambia el estado de un usuario a activo/inactivo (solo administrador)."""
    usuario = db.query(Usuario).filter(Usuario.id == usuario_id).first()
    if usuario is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail='Usuario no encontrado.',
        )
    usuario.estado = body.estado
    db.commit()
    return {'message': 'Estado del usuario actualizado.', 'estado': usuario.estado}


@router.delete('/{usuario_id}')
def eliminar_usuario(
    usuario_id: int,
    db: Session = Depends(get_db),
    _: Usuario = Depends(require_roles('administrador')),
):
    """Elimina un usuario (solo administrador)."""
    usuario = db.query(Usuario).filter(Usuario.id == usuario_id).first()
    if usuario is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail='Usuario no encontrado.',
        )
    db.delete(usuario)
    db.commit()
    return {'message': 'Usuario eliminado exitosamente.'}

router_productos:
"""
Rutas de productos: /api/productos
- GET    /api/productos                → listar productos (público)
- GET    /api/productos/categorias     → listar categorías (público)
- GET    /api/productos/{id}           → consultar producto (público)
- POST   /api/productos                → crear producto (admin o empleado)
- PUT    /api/productos/{id}           → actualizar producto (admin o empleado)
- DELETE /api/productos/{id}           → eliminar producto (solo admin)
"""
from fastapi import APIRouter, Depends, HTTPException, status
from sqlalchemy.orm import Session

from ..database import get_db
from ..models import CategoriaProducto, Producto, Usuario
from ..schemas import CategoriaOut, ProductoCreate, ProductoOut, ProductoUpdate
from ..security import require_roles

router = APIRouter(prefix='/api/productos', tags=['Productos'])


@router.get('')
def listar_productos(db: Session = Depends(get_db)):
    """Lista todos los productos con su categoría."""
    productos = db.query(Producto).order_by(Producto.fecha_creacion.desc()).all()
    return {
        'products': [
            {
                **ProductoOut.model_validate(p).model_dump(),
                'categoria_nombre': p.categoria.nombre if p.categoria else None,
            }
            for p in productos
        ]
    }


@router.get('/categorias')
def listar_categorias(db: Session = Depends(get_db)):
    """Lista las categorías de productos."""
    categorias = db.query(CategoriaProducto).order_by(CategoriaProducto.id).all()
    return {
        'categories': [
            CategoriaOut.model_validate(c).model_dump() for c in categorias
        ]
    }


@router.get('/{producto_id}')
def obtener_producto(producto_id: int, db: Session = Depends(get_db)):
    """Consulta un producto por ID."""
    producto = db.query(Producto).filter(Producto.id == producto_id).first()
    if producto is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail='Producto no encontrado.',
        )
    data = ProductoOut.model_validate(producto).model_dump()
    data['categoria_nombre'] = producto.categoria.nombre if producto.categoria else None
    return {'product': data}


@router.post('', status_code=status.HTTP_201_CREATED)
def crear_producto(
    body: ProductoCreate,
    db: Session = Depends(get_db),
    _: Usuario = Depends(require_roles('administrador', 'empleado')),
):
    """Crea un producto nuevo (solo administrador o empleado)."""
    producto = Producto(
        nombre=body.nombre,
        descripcion=body.descripcion,
        precio=body.precio,
        stock=body.stock,
        imagen_url=body.imagen_url,
        categoria_id=body.categoria_id,
        estado='activo',
    )
    db.add(producto)
    db.commit()
    db.refresh(producto)
    return {
        'message': 'Producto creado exitosamente.',
        'product': {'id': producto.id, 'nombre': producto.nombre, 'precio': float(producto.precio), 'stock': producto.stock},
    }


@router.put('/{producto_id}')
def actualizar_producto(
    producto_id: int,
    body: ProductoUpdate,
    db: Session = Depends(get_db),
    _: Usuario = Depends(require_roles('administrador', 'empleado')),
):
    """Actualiza un producto (solo administrador o empleado)."""
    producto = db.query(Producto).filter(Producto.id == producto_id).first()
    if producto is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail='Producto no encontrado.',
        )
    data = body.model_dump(exclude_unset=True, exclude_none=True)
    for campo, valor in data.items():
        setattr(producto, campo, valor)
    db.commit()
    return {'message': 'Producto actualizado exitosamente.'}


@router.delete('/{producto_id}')
def eliminar_producto(
    producto_id: int,
    db: Session = Depends(get_db),
    _: Usuario = Depends(require_roles('administrador')),
):
    """Elimina un producto (solo administrador)."""
    producto = db.query(Producto).filter(Producto.id == producto_id).first()
    if producto is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail='Producto no encontrado.',
        )
    db.delete(producto)
    db.commit()
    return {'message': 'Producto eliminado exitosamente.'}

